// =========================================================================
// STAGE: Normalize Source A (GDELT News Signals)
// Documented API: https://api.gdeltproject.org/api/v2/doc/doc
// Common Normalized Structure:
// {
//   keyword, normalized_keyword, country_code, category, source,
//   search_interest, news_volume, news_activity_score, news_velocity, ranking,
//   related_queries, related_articles, observed_at
// }
// Important:
// - GDELT provides news attention, NOT search interest (search_interest = null).
// - Calculates news_activity_score (0-100) for current batch recency.
// - Leaves news_velocity = null (reserved for historical multi-snapshot analysis).
// =========================================================================

const rawInput = $input.first()?.json || {};
const config = $('Workflow Configuration').first()?.json || { country_code: 'US' };

if (rawInput.error || (rawInput.statusCode && rawInput.statusCode >= 400)) {
  console.warn(`[GDELT Warning] Source A failed: ${rawInput.error || rawInput.statusCode}`);
  return [{
    json: {
      _telemetry: {
        source: 'gdelt',
        status: 'FAILED',
        error: rawInput.error || `HTTP ${rawInput.statusCode}`,
        records_received: 0,
        records_normalized: 0
      }
    }
  }];
}

const articles = rawInput.articles || (typeof rawInput.data === 'object' ? rawInput.data.articles : []) || [];
if (!Array.isArray(articles) || articles.length === 0) {
  return [{
    json: {
      _telemetry: {
        source: 'gdelt',
        status: 'EMPTY',
        error: null,
        records_received: 0,
        records_normalized: 0
      }
    }
  }];
}

const now = new Date().toISOString();
const topicMap = new Map();

for (const art of articles) {
  if (!art.title) continue;
  const rawTitle = art.title.trim();

  const norm = rawTitle
    .normalize('NFKC')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

  if (!topicMap.has(norm)) {
    topicMap.set(norm, {
      keyword: rawTitle,
      normalized_keyword: norm,
      country_code: (art.sourcecountry || config.country_code).toUpperCase(),
      category: 'News',
      source: 'gdelt',
      articles: [],
      domains: new Set(),
      timestamps: []
    });
  }

  const entry = topicMap.get(norm);
  entry.articles.push({
    title: rawTitle,
    url: art.url || '',
    domain: art.domain || null,
    seendate: art.seendate || null
  });
  if (art.domain) entry.domains.add(art.domain);
  if (art.seendate) entry.timestamps.push(art.seendate);
}

const items = [];
for (const entry of topicMap.values()) {
  const newsVolume = entry.articles.length;
  let newsActivityScore = null;
  if (entry.timestamps.length > 0) {
    newsActivityScore = Math.min(100, Math.round((newsVolume / Math.max(1, entry.domains.size)) * 20));
  }

  items.push({
    json: {
      keyword: entry.keyword,
      normalized_keyword: entry.normalized_keyword,
      country_code: entry.country_code,
      category: entry.category,
      source: entry.source,
      search_interest: null,
      news_volume: newsVolume,
      news_activity_score: newsActivityScore,
      news_velocity: null,
      ranking: null,
      related_queries: [],
      related_articles: entry.articles.slice(0, 5),
      observed_at: now,
      _telemetry: {
        source: 'gdelt',
        status: 'HEALTHY',
        error: null,
        records_received: articles.length,
        records_normalized: topicMap.size
      }
    }
  });
}

return items;

// =========================================================================
// STAGE: Normalize Source B (Google Trends Public RSS)
// Public Endpoint: https://trends.google.com/trending/rss?geo=...
// Secondary search-interest signal. Isolated and replaceable.
// Important:
// - Search interest is an approximate bucket, NOT an exact count.
// - Feed order is sequence only, NOT a factual popularity ranking.
// - Leaves news_velocity = null (reserved for historical multi-snapshot analysis).
// =========================================================================

const rawInput = $input.first()?.json || {};
const config = $('Workflow Configuration').first()?.json || { country_code: 'US' };

if (rawInput.error || (rawInput.statusCode && rawInput.statusCode >= 400)) {
  console.warn(`[Google Trends Warning] Source B failed: ${rawInput.error || rawInput.statusCode}`);
  return [{
    json: {
      _telemetry: {
        source: 'google_trends_rss',
        status: 'FAILED',
        error: rawInput.error || `HTTP ${rawInput.statusCode}`,
        records_received: 0,
        records_normalized: 0
      }
    }
  }];
}

const rawXml = rawInput.data || rawInput.body || rawInput;
const xmlText = typeof rawXml === 'string' ? rawXml : JSON.stringify(rawXml);

if (!xmlText || !xmlText.includes('<item>')) {
  return [{
    json: {
      _telemetry: {
        source: 'google_trends_rss',
        status: 'EMPTY',
        error: 'No <item> tags found',
        records_received: 0,
        records_normalized: 0
      }
    }
  }];
}

const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
let match;
let rank = 1;
let count = 0;
const now = new Date().toISOString();

while ((match = itemRegex.exec(xmlText)) !== null) {
  count++;
  const itemContent = match[1];

  const titleMatch = /<title>([\s\S]*?)<\/title>/i.exec(itemContent);
  const rawKeyword = titleMatch ? titleMatch[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1').trim() : '';
  if (!rawKeyword) continue;

  const trafficMatch = /<ht:approx_traffic>([\s\S]*?)<\/ht:approx_traffic>/i.exec(itemContent);
  let searchInterest = null;
  if (trafficMatch) {
    const rawTraffic = trafficMatch[1].trim();
    const numOnly = rawTraffic.replace(/\D/g, '');
    if (numOnly) {
      let val = parseInt(numOnly, 10);
      if (/k/i.test(rawTraffic)) val *= 1000;
      else if (/m/i.test(rawTraffic)) val *= 1000000;
      searchInterest = val;
    }
  }

  const pubDateMatch = /<pubDate>([\s\S]*?)<\/pubDate>/i.exec(itemContent);
  const pubDate = pubDateMatch ? pubDateMatch[1].trim() : null;

  const relatedQueries = [];
  const relatedArticles = [];
  const newsItemRegex = /<ht:news_item>([\s\S]*?)<\/ht:news_item>/gi;
  let newsMatch;

  while ((newsMatch = newsItemRegex.exec(itemContent)) !== null) {
    const nContent = newsMatch[1];
    const nTitleMatch = /<ht:news_item_title>([\s\S]*?)<\/ht:news_item_title>/i.exec(nContent);
    const nUrlMatch = /<ht:news_item_url>([\s\S]*?)<\/ht:news_item_url>/i.exec(nContent);
    const nSourceMatch = /<ht:news_item_source>([\s\S]*?)<\/ht:news_item_source>/i.exec(nContent);

    const nTitle = nTitleMatch ? nTitleMatch[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1').replace(/&apos;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&').trim() : '';
    const nUrl = nUrlMatch ? nUrlMatch[1].trim() : '';
    const nSource = nSourceMatch ? nSourceMatch[1].trim() : '';

    if (nTitle) {
      if (!relatedQueries.includes(nTitle)) relatedQueries.push(nTitle);
      relatedArticles.push({ title: nTitle, url: nUrl, source: nSource });
    }
  }

  const normalizedKeyword = rawKeyword
    .normalize('NFKC')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

  items.push({
    json: {
      keyword: rawKeyword,
      normalized_keyword: normalizedKeyword,
      country_code: config.country_code,
      category: 'General',
      source: 'google_trends_rss',
      search_interest: searchInterest,
      news_volume: relatedArticles.length > 0 ? relatedArticles.length : null,
      news_activity_score: null,
      news_velocity: null,
      ranking: rank,
      related_queries: relatedQueries,
      related_articles: relatedArticles,
      observed_at: pubDate ? new Date(pubDate).toISOString() : now,
      _telemetry: {
        source: 'google_trends_rss',
        status: 'HEALTHY',
        error: null,
        records_received: count,
        records_normalized: rank
      }
    }
  });
  rank++;
}

return items;

// =========================================================================
// STAGE: Normalize Source C (Reputable Public RSS / News Feeds)
// Secondary news corroboration signal.
// Important:
// - search_interest = null. Do not use RSS counts as search volume.
// - Leaves news_velocity = null (reserved for historical multi-snapshot analysis).
// =========================================================================

const rawInput = $input.first()?.json || {};
const config = $('Workflow Configuration').first()?.json || { country_code: 'US' };

if (rawInput.error || (rawInput.statusCode && rawInput.statusCode >= 400)) {
  console.warn(`[RSS Feeds Warning] Source C failed: ${rawInput.error || rawInput.statusCode}`);
  return [{
    json: {
      _telemetry: {
        source: 'rss_feed',
        status: 'FAILED',
        error: rawInput.error || `HTTP ${rawInput.statusCode}`,
        records_received: 0,
        records_normalized: 0
      }
    }
  }];
}

const rawXml = rawInput.data || rawInput.body || rawInput;
const xmlText = typeof rawXml === 'string' ? rawXml : JSON.stringify(rawXml);

if (!xmlText || !xmlText.includes('<item>')) {
  return [{
    json: {
      _telemetry: {
        source: 'rss_feed',
        status: 'EMPTY',
        error: 'No <item> tags found',
        records_received: 0,
        records_normalized: 0
      }
    }
  }];
}

const items = [];
const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
let match;
let count = 0;
const now = new Date().toISOString();

while ((match = itemRegex.exec(xmlText)) !== null) {
  count++;
  const itemContent = match[1];

  const titleMatch = /<title>([\s\S]*?)<\/title>/i.exec(itemContent);
  let rawTitle = titleMatch ? titleMatch[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1').replace(/&apos;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&').trim() : '';
  if (!rawTitle) continue;

  const cleanKeyword = rawTitle.replace(/\s*-\s*[^-]+$/, '').trim() || rawTitle;
  const linkMatch = /<link>([\s\S]*?)<\/link>/i.exec(itemContent);
  const url = linkMatch ? linkMatch[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/gi, '$1').trim() : '';
  const pubDateMatch = /<pubDate>([\s\S]*?)<\/pubDate>/i.exec(itemContent);
  const pubDate = pubDateMatch ? pubDateMatch[1].trim() : null;
  const sourceMatch = /<source[^>]*>([\s\S]*?)<\/source>/i.exec(itemContent);
  const sourceName = sourceMatch ? sourceMatch[1].trim() : 'News RSS';

  const normalizedKeyword = cleanKeyword
    .normalize('NFKC')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

  items.push({
    json: {
      keyword: cleanKeyword,
      normalized_keyword: normalizedKeyword,
      country_code: config.country_code,
      category: 'News',
      source: 'rss_feed',
      search_interest: null,
      news_volume: 1,
      news_activity_score: null,
      news_velocity: null,
      ranking: null,
      related_queries: [],
      related_articles: [{ title: rawTitle, url, source: sourceName }],
      observed_at: pubDate ? new Date(pubDate).toISOString() : now,
      _telemetry: {
        source: 'rss_feed',
        status: 'HEALTHY',
        error: null,
        records_received: count,
        records_normalized: items.length + 1
      }
    }
  });
}

return items;

// =========================================================================
// STAGE: Deduplicate Topics (Conservative Deduplication & Evidence Preservation)
// Deduplicates using:
// 1. Exact normalized_keyword + country_code
// 2. Conservative wording variations (Jaccard >= 0.80, min 3 words, or strict subset <= 1 word diff)
// Preserves source attribution and source-level observations without destroying evidence.
// Outputs diagnostic telemetry when all sources fail or return zero records.
// =========================================================================

const rawItems = $input.all();
const candidates = [];
const telemetries = [];

for (const item of rawItems) {
  const data = item.json;
  if (data._telemetry) {
    telemetries.push(data._telemetry);
  }
  if (data.keyword && data.normalized_keyword) {
    candidates.push(data);
  }
}

if (candidates.length === 0) {
  const allFailed = telemetries.every(t => t.status === 'FAILED' || t.status === 'EMPTY');
  return [{
    json: {
      _diagnostic: {
        is_empty_result: true,
        all_sources_failed: allFailed,
        message: allFailed
          ? 'CRITICAL: All trend detection sources failed or returned empty data.'
          : 'Zero candidates found across healthy sources.',
        source_health: telemetries,
        timestamp: new Date().toISOString()
      }
    }
  }];
}

const stopWords = new Set([
  'the', 'a', 'an', 'in', 'on', 'at', 'to', 'for', 'of', 'and', 'or', 'is',
  'are', 'was', 'were', 'with', 'by', 'from', 'as', 'that', 'this', 'it', 'its'
]);

function getSignificantTokens(str) {
  return str
    .toLowerCase()
    .replace(/[^\w\s]/g, '')
    .split(/\s+/)
    .filter((w) => w.length > 2 && !stopWords.has(w));
}

function areConservativeDuplicates(kw1, kw2) {
  if (kw1 === kw2) return true;
  const t1 = getSignificantTokens(kw1);
  const t2 = getSignificantTokens(kw2);

  if (t1.length < 3 || t2.length < 3) return false;

  const s1 = new Set(t1);
  const s2 = new Set(t2);

  let common = 0;
  for (const token of s1) {
    if (s2.has(token)) common++;
  }

  const unionSize = new Set([...s1, ...s2]).size;
  const jaccard = common / unionSize;
  if (jaccard >= 0.80) return true;

  const smaller = s1.size <= s2.size ? s1 : s2;
  const larger = s1.size <= s2.size ? s2 : s1;
  if (common === smaller.size && larger.size - smaller.size <= 1 && smaller.size >= 3) {
    return true;
  }

  return false;
}

const merged = [];

for (const cand of candidates) {
  let matched = null;
  for (const existing of merged) {
    if (
      existing.country_code === cand.country_code &&
      areConservativeDuplicates(existing.normalized_keyword, cand.normalized_keyword)
    ) {
      matched = existing;
      break;
    }
  }

  if (!matched) {
    merged.push({
      ...cand,
      sources: [cand.source],
      source_observations: [
        {
          source: cand.source,
          keyword: cand.keyword,
          search_interest: cand.search_interest,
          news_volume: cand.news_volume,
          observed_at: cand.observed_at
        }
      ],
      related_queries: [...(cand.related_queries || [])],
      related_articles: [...(cand.related_articles || [])]
    });
  } else {
    matched.source_observations.push({
      source: cand.source,
      keyword: cand.keyword,
      search_interest: cand.search_interest,
      news_volume: cand.news_volume,
      observed_at: cand.observed_at
    });

    if (!matched.sources.includes(cand.source)) {
      matched.sources.push(cand.source);
      matched.source = matched.sources.join(' + ');
    }

    if (cand.search_interest !== null) {
      matched.search_interest =
        matched.search_interest !== null
          ? Math.max(matched.search_interest, cand.search_interest)
          : cand.search_interest;
    }

    if (cand.news_volume !== null) {
      matched.news_volume = (matched.news_volume || 0) + cand.news_volume;
    }

    for (const q of cand.related_queries || []) {
      if (!matched.related_queries.includes(q)) {
        matched.related_queries.push(q);
      }
    }

    for (const art of cand.related_articles || []) {
      const exists = matched.related_articles.some(
        (a) => (art.url && a.url === art.url) || a.title === art.title
      );
      if (!exists) {
        matched.related_articles.push(art);
      }
    }

    if (cand.observed_at && (!matched.observed_at || cand.observed_at > matched.observed_at)) {
      matched.observed_at = cand.observed_at;
    }
  }
}

return merged.map(data => ({ json: data }));

// =========================================================================
// STAGE: Calculate Trend Signals
// Calculates separate signals (normalized 0–100 only when sufficient data exists):
// 1. news_activity_score
// 2. search_interest_score
// 3. source_confirmation_score
// 4. freshness_score
// Outputs available_signals and missing_signals for auditability.
// If a signal is unavailable, do NOT fabricate it (leave as null).
// =========================================================================

const nowMs = Date.now();

return $input.all().map(item => {
  const data = item.json;
  if (data._diagnostic) return item;

  const available_signals = [];
  const missing_signals = [];

  // 1. news_activity_score (0–100 or null)
  let news_activity_score = null;
  if (data.news_activity_score !== null && data.news_activity_score !== undefined) {
    news_activity_score = Math.min(100, Math.max(0, data.news_activity_score));
    available_signals.push('news_activity');
  } else if (data.news_volume && data.news_volume > 1) {
    news_activity_score = Math.min(100, Math.round(data.news_volume * 15));
    available_signals.push('news_activity');
  } else {
    missing_signals.push('news_activity');
  }

  // Historical news velocity is explicitly reserved for multi-snapshot analysis
  missing_signals.push('historical_news_velocity');

  // 2. search_interest_score (0–100 or null)
  let search_interest_score = null;
  if (data.search_interest !== null && data.search_interest !== undefined) {
    if (data.search_interest >= 500000) search_interest_score = 100;
    else if (data.search_interest >= 200000) search_interest_score = 85;
    else if (data.search_interest >= 100000) search_interest_score = 70;
    else if (data.search_interest >= 50000) search_interest_score = 55;
    else if (data.search_interest >= 20000) search_interest_score = 40;
    else if (data.search_interest >= 5000) search_interest_score = 30;
    else search_interest_score = 20;
    available_signals.push('search_interest');
  } else {
    missing_signals.push('search_interest');
  }

  // 3. source_confirmation_score (0–100)
  let source_confirmation_score = 30;
  const numSources = (data.sources || [data.source]).length;
  const numArticles = (data.related_articles || []).length;
  if (numSources >= 3 || numArticles >= 5) {
    source_confirmation_score = 100;
  } else if (numSources >= 2 || numArticles >= 3) {
    source_confirmation_score = 75;
  } else if (numArticles >= 2) {
    source_confirmation_score = 50;
  }
  available_signals.push('source_confirmation');

  // 4. freshness_score (0–100 or null)
  let freshness_score = null;
  if (data.observed_at) {
    const ageHours = (nowMs - new Date(data.observed_at).getTime()) / (1000 * 60 * 60);
    if (ageHours < 2) freshness_score = 100;
    else if (ageHours < 6) freshness_score = 85;
    else if (ageHours < 12) freshness_score = 65;
    else if (ageHours < 24) freshness_score = 40;
    else freshness_score = 20;
    available_signals.push('freshness');
  } else {
    missing_signals.push('freshness');
  }

  return {
    json: {
      ...data,
      news_activity_score,
      search_interest_score,
      source_confirmation_score,
      freshness_score,
      available_signals,
      missing_signals
    }
  };
});

// =========================================================================
// STAGE: Calculate Initial Trend Score & Signal Completeness
// Heuristic component weights:
// - News Activity: 35%
// - Search Interest: 30%
// - Source Confirmation / Diversity: 20%
// - Freshness: 15%
// Formula: Only include components where underlying data exists.
// trend_score = sum(weight_i * score_i) / sum(weight_i for present scores)
// signal_completeness_score = sum(weight_i for present scores) * 100
// confidence_score = alias for signal_completeness_score (backwards compatibility)
// =========================================================================

return $input.all().map(item => {
  const data = item.json;
  if (data._diagnostic) return item;

  const components = [
    { score: data.news_activity_score, weight: 0.35 },
    { score: data.search_interest_score, weight: 0.30 },
    { score: data.source_confirmation_score, weight: 0.20 },
    { score: data.freshness_score, weight: 0.15 }
  ];

  let weightedSum = 0;
  let availableWeight = 0;

  for (const comp of components) {
    if (comp.score !== null && comp.score !== undefined) {
      weightedSum += comp.score * comp.weight;
      availableWeight += comp.weight;
    }
  }

  let trend_score = null;
  let signal_completeness_score = 0;

  if (availableWeight > 0) {
    trend_score = Math.min(100, Math.round(weightedSum / availableWeight));
    signal_completeness_score = Math.round(availableWeight * 100);
  }

  return {
    json: {
      ...data,
      trend_score,
      signal_completeness_score,
      confidence_score: signal_completeness_score
    }
  };
});

// =========================================================================
// STAGE: Classify Review Risk (Deterministic Editorial Routing)
// Editorial policy:
// - Identifies topics requiring human editorial review (deaths, disasters,
//   violence, terror, elections, political conflicts, medical emergencies,
//   allegations involving individuals, financial crises).
// - Only an editorial review signal; does NOT determine truth or falsity.
// - Must NOT automatically publish content.
// - When uncertain, flag for human review.
// =========================================================================

const HIGH_RISK_TERMS = [
  'death', 'dead', 'dies', 'died', 'fatal', 'fatality', 'casualty', 'casualties',
  'killing', 'killed', 'murder', 'murdered', 'suicide', 'shooting', 'shot', 'gunman',
  'crash', 'attack', 'bomb', 'bombing', 'terror', 'hostage', 'war', 'conflict',
  'airstrike', 'missile', 'election', 'voting', 'ballot', 'coup', 'arrest',
  'arrested', 'indicted', 'indictment', 'fraud', 'scandal', 'emergency',
  'disaster', 'outbreak', 'virus', 'epidemic', 'pandemic', 'overdose',
  'bankruptcy', 'collapse', 'lawsuit', 'sexual assault', 'misconduct'
];

const now = new Date().toISOString();

return $input.all().map(item => {
  const data = item.json;
  if (data._diagnostic) return item;

  const kw = data.normalized_keyword || '';
  const matchedTerms = HIGH_RISK_TERMS.filter(term => kw.includes(term));

  let risk_score = 10;
  let requires_review = false;

  if (matchedTerms.length > 0) {
    risk_score = 75;
    requires_review = true;
  }

  return {
    json: {
      ...data,
      search_volume: data.search_interest !== null ? data.search_interest : null,
      trend_velocity: null,
      opportunity_score: data.trend_score,
      risk_score: risk_score,
      status: 'detected',
      requires_review: requires_review,
      risk_reasons: matchedTerms,
      first_detected_at: now,
      last_detected_at: now,
      created_at: now,
      updated_at: now
    }
  };
});
